// Independent logic verification for the seed-randomization changes
// (PR #234 follow-up). Simulates each test's data-generation formulas
// with a stand-in RNG and asserts the design invariants.
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <limits>
#include <random>
#include <set>
#include <vector>

static std::mt19937_64 rng;

static uint32_t r32() { return (uint32_t)rng(); }
static uint64_t r64() { return rng(); }
// frandomf_scale/frandom_scale semantics: uniform in [0, scale)
static float frand_scale_f(float scale) {
    return (float)((double)rng() / (double)std::numeric_limits<uint64_t>::max() * scale);
}
static double frand_scale_d(double scale) {
    return (double)rng() / (double)std::numeric_limits<uint64_t>::max() * scale;
}

static int failures = 0;
#define CHECK(cond, msg)                                                     \
    do {                                                                     \
        if (!(cond)) {                                                       \
            printf("FAIL: %s\n", msg);                                       \
            ++failures;                                                      \
        }                                                                    \
    } while (0)

// ---- sme_fmopa_stress_arm: |a|,|b| < 0.5625; golden self-consistent ----
static void fmopa_check(long n, long rounds)
{
    size_t vc = (size_t)rounds * n, nn = (size_t)n * n;
    std::vector<float> a(vc), b(vc);
    std::vector<float> golden(nn, 0.0f), golden2(nn, 0.0f);
    for (size_t i = 0; i < vc; ++i) {
        a[i] = frand_scale_f(1.125f) - 0.5625f;
        b[i] = frand_scale_f(1.125f) - 0.5625f;
        CHECK(std::isfinite(a[i]) && std::fabs(a[i]) < 0.5625f, "fmopa |a|<0.5625");
        CHECK(std::isfinite(b[i]) && std::fabs(b[i]) < 0.5625f, "fmopa |b|<0.5625");
    }
    for (long k = 0; k < rounds; ++k)
        for (long r = 0; r < n; ++r)
            for (long c = 0; c < n; ++c)
                golden[(size_t)r * n + c] = std::fmaf(
                    a[(size_t)k * n + r], b[(size_t)k * n + c],
                    golden[(size_t)r * n + c]);
    // Independent recompute (same op order) must be bit-identical.
    for (long k = 0; k < rounds; ++k)
        for (long r = 0; r < n; ++r)
            for (long c = 0; c < n; ++c)
                golden2[(size_t)r * n + c] = std::fmaf(
                    a[(size_t)k * n + r], b[(size_t)k * n + c],
                    golden2[(size_t)r * n + c]);
    CHECK(0 == memcmp(golden.data(), golden2.data(), nn * sizeof(float)),
          "fmopa golden self-consistent (bit-exact recompute)");
    // 64-step sums must stay finite and below 21.
    for (size_t i = 0; i < nn; ++i) {
        CHECK(std::isfinite(golden[i]) && std::fabs(golden[i]) < 21.0f,
              "fmopa 64-step sum < 21");
    }
}

// ---- sme_za_tileview_arm: distinct, exact integers ----
static void za_check(long n)
{
    std::vector<double> a((size_t)n * n), b((size_t)n * n);
    std::set<double> distinct;
    for (long i = 0; i < n; ++i)
        for (long j = 0; j < n; ++j) {
            size_t ij = (size_t)i * n + j;
            a[ij] = (double)((r64() % 1024) * 64 + (i * n + j));
            b[ij] = (double)((r64() % 1024) * 64 + (i * n + j));
            distinct.insert(a[ij]);
            distinct.insert(b[ij]);
        }
    CHECK(distinct.size() == (size_t)n * n * 2, "za_tileview all-distinct (a and b)");
    for (double v : a)
        CHECK(v == std::floor(v) && v >= 0, "za_tileview exact nonneg integer");
}

// ---- sve512_stencil_axis_arm: scalar reference ----
static const size_t RADIUS = 6, B_TILE = 16, coord = 10, extent = 56,
                    stride = 64;
static const size_t ITER = 100000000;

static void stencil_expected(const std::vector<double> &src, double out[B_TILE])
{
    const double *s = src.data() + coord * stride * B_TILE;
    for (size_t j = 0; j < B_TILE; ++j) out[j] = 0.0;
    for (size_t r = 1; r <= RADIUS; ++r) {
        ptrdiff_t off = (ptrdiff_t)(r * stride) * B_TILE;
        for (size_t j = 0; j < B_TILE; ++j) {
            double delta = 0.0;
            if (coord >= r) delta += s[-off + (ptrdiff_t)j];
            if (coord + r < extent) delta += s[+off + (ptrdiff_t)j];
            out[j] += 0.125 * delta;
        }
    }
    for (size_t j = 0; j < B_TILE; ++j) out[j] *= (double)ITER;
}

static void stencil_check(bool fixed_src)
{
    std::vector<double> src(extent * stride * B_TILE);
    for (size_t i = 0; i < src.size(); ++i)
        src[i] = fixed_src ? (double)(i % B_TILE + 1) : (double)(1 + r32() % 256);
    double expected[B_TILE];
    stencil_expected(src, expected);
    if (fixed_src) {
        // Degenerate case: must reproduce the original analytic formula
        // bit-exactly.
        for (size_t j = 0; j < B_TILE; ++j) {
            double analytic = 1.5 * (double)ITER * (double)(j + 1);
            CHECK(expected[j] == analytic, "stencil ref == analytic on fixed src");
        }
    } else {
        // Random case: expected stays an exact 1/8-grid value below 2^53.
        for (size_t j = 0; j < B_TILE; ++j) {
            CHECK(std::isfinite(expected[j]) && expected[j] < 9.0e15,
                  "stencil expected < 2^53");
            CHECK(std::fmod(expected[j] * 8.0, 1.0) == 0.0,
                  "stencil expected on exact 1/8 grid");
        }
        // Order independence: reverse-r accumulation must give the same
        // bits (proves the hw accumulation order cannot cause a mismatch).
        const double *s = src.data() + coord * stride * B_TILE;
        double rev[B_TILE] = {};
        for (size_t rr = RADIUS; rr >= 1; --rr) {
            ptrdiff_t off = (ptrdiff_t)(rr * stride) * B_TILE;
            for (size_t j = 0; j < B_TILE; ++j) {
                double delta = 0.0;
                if (coord >= rr) delta += s[-off + (ptrdiff_t)j];
                if (coord + rr < extent) delta += s[+off + (ptrdiff_t)j];
                rev[j] += 0.125 * delta;
            }
        }
        for (size_t j = 0; j < B_TILE; ++j) {
            CHECK((rev[j] * (double)ITER) == expected[j],
                  "stencil expected order-independent");
        }
    }
}

// ---- fpu_special_values_sve: random finite entries ----
static void fpu_check()
{
    for (int i = 12; i < 16; ++i) {
        float f = (r32() & 1 ? -1.0f : 1.0f) * frand_scale_f(1.0f);
        double d = (r32() & 1 ? -1.0 : 1.0) * frand_scale_d(1.0);
        CHECK(std::isfinite(f) && !std::isnan(f) && std::fabs(f) < 1.0f,
              "fpu_special f32 random finite |v|<1");
        CHECK(std::isfinite(d) && !std::isnan(d) && std::fabs(d) < 1.0,
              "fpu_special f64 random finite |v|<1");
    }
}

int main()
{
    std::vector<uint64_t> snapshot1, snapshot2;
    // Fragment A
    rng.seed(111);
    fmopa_check(8, 4);
    za_check(8);
    stencil_check(false);
    fpu_check();
    // Fragment B (different seed): re-run and record a data sample for a
    // cross-fragment difference check.
    rng.seed(222);
    fmopa_check(8, 4);
    za_check(8);
    stencil_check(false);
    fpu_check();

    // Cross-fragment randomness: same generators, two seeds -> different.
    std::vector<double> s1, s2;
    rng.seed(111);
    for (int i = 0; i < 8; ++i) s1.push_back(frand_scale_d(1.0));
    rng.seed(222);
    for (int i = 0; i < 8; ++i) s2.push_back(frand_scale_d(1.0));
    CHECK(s1 != s2, "different seeds -> different data");

    // Fixed-src degenerate check of the stencil reference.
    stencil_check(true);

    printf(failures ? "RESULT: %d FAILURES\n" : "RESULT: ALL CHECKS PASSED\n",
           failures);
    return failures ? 1 : 0;
}

