/* stencil_axis_dual.c — dual-channel extraction of sdcshield test
 * `sve512_stencil_axis_arm` (PR #237 seed-randomized form) for CHAOS/gem5
 * SE-O3 fault injection (plan 2026-10-13-sve-sme-fi-eval Task 4).
 *
 * Channel A: the SVE stencil-accumulation kernel (svmla over the two
 * radius-offset vectors, exactly the test's axis_generic_16x2 shape:
 * res += 0.125 * (src[coord-r] + src[coord+r]) per r, both directions
 * valid at coord=10/RADIUS=6) compared bit-exactly against the runtime
 * scalar reference. Exactness: all terms are integer multiples of 1/8,
 * per-call increment < 12*0.125*512 = 768 and the ITERS-scaled result
 * stays below 2^53 — order-independent accumulation, bit-exact equality
 * (same proof as the sdcshield test).
 *
 *   fixed  — src[i] = i % B_TILE + 1 (the pre-PR#237 pattern) with the
 *            analytic expected 1.5*ITERS*(j+1)
 *   random — src[i] = 1 + xorshift32()%256 (the PR #237 form) with the
 *            runtime scalar reference
 *
 * Channel B: FNV-1a over the hardware result lanes.
 *
 * ITERS is sized for gem5 O3 (~seconds per run; the sdcshield test's 1e8
 * inner iterations are a real-hardware timed-loop quantity).
 *
 * argv: [fixed|random] [seed]
 * Build: clang -static -O2 -march=armv9-a+sve+sme -Wall -Wextra \
 *          -o stencil_axis_dual stencil_axis_dual.c -lm
 * Run:   gem5.opt configs/se/arm_chaos.py --cmd <bin> --sve_vl 4 \
 *          --workload_args "random 1"
 */
#include <arm_sve.h>
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

#define RADIUS  6
#define B_TILE  16
#define COORD   10
#define EXTENT  56
#define STRIDE  64
#define ITERS   2000

static uint32_t xs_state;
static uint32_t xs32(void)
{
    xs_state ^= xs_state << 13;
    xs_state ^= xs_state >> 17;
    xs_state ^= xs_state << 5;
    return xs_state;
}

static unsigned g_fails = 0;
static uint64_t fnv = 1469598103934665603ULL;
static void fnv_u64(uint64_t v)
{
    for (int i = 0; i < 8; ++i) {
        fnv ^= (v >> (8 * i)) & 0xFF;
        fnv *= 1099511628211ULL;
    }
}

int main(int argc, char **argv)
{
    const char *mode = (argc > 1) ? argv[1] : "random";
    const uint32_t seed = (argc > 2) ? (uint32_t)strtoul(argv[2], 0, 0) : 1;
    const int randomize = (strcmp(mode, "random") == 0);
    xs_state = seed ? seed : 1;

    /* Layout: [extent][stride][B_TILE] doubles (the test's geometry). */
    static double src[EXTENT * STRIDE * B_TILE];
    for (size_t i = 0; i < sizeof src / sizeof src[0]; ++i)
        src[i] = randomize ? (double)(1 + xs32() % 256)
                           : (double)(i % B_TILE + 1);
    const double *s_base = src + COORD * STRIDE * B_TILE;

    /* Runtime scalar reference (PR #237 run-side logic): per lane j one
     * kernel call adds sum_r 0.125*(src[coord-r][j] + src[coord+r][j]). */
    double expected[B_TILE];
    for (int j = 0; j < B_TILE; ++j) expected[j] = 0.0;
    for (size_t r = 1; r <= RADIUS; ++r) {
        const ptrdiff_t off = (ptrdiff_t)(r * STRIDE) * B_TILE;
        for (int j = 0; j < B_TILE; ++j) {
            double delta = 0.0;
            if (COORD >= (int)r)
                delta += s_base[-off + j];
            if (COORD + r < EXTENT)
                delta += s_base[+off + j];
            expected[j] += 0.125 * delta;
        }
    }
    if (!randomize) {
        /* fixed mode degenerates to the pre-PR#237 analytic formula —
         * assert the reference agrees with it (kernel self-check). */
        for (int j = 0; j < B_TILE; ++j)
            if (expected[j] != 1.5 * (double)(j + 1)) {
                fprintf(stderr, "scalar ref != analytic at lane %d: %f vs %f\n",
                        j, expected[j], 1.5 * (double)(j + 1));
                ++g_fails;
            }
    }
    for (int j = 0; j < B_TILE; ++j)
        expected[j] *= (double)ITERS;

    /* The accumulation kernel: ITERS rounds of the two-vector svmla
     * pattern (res0/res1 accumulate; 0.125 coefficients). */
    const svbool_t ptrue = svptrue_b64();
    double coeff[RADIUS + 1] = {};
    for (size_t r = 1; r <= RADIUS; ++r) coeff[r] = 0.125;
    svfloat64_t res0 = svdup_f64(0.0);
    svfloat64_t res1 = svdup_f64(0.0);

    for (int it = 0; it < ITERS; ++it) {
        for (size_t r = 1; r <= RADIUS; ++r) {
            const ptrdiff_t off = (ptrdiff_t)(r * STRIDE) * B_TILE;
            const svfloat64_t c = svdup_f64(coeff[r]);
            if (COORD >= (int)r) {
                res0 = svmla_f64_m(ptrue, res0,
                                   svld1_f64(ptrue, s_base - off), c);
                res1 = svmla_f64_m(ptrue, res1,
                                   svld1_f64(ptrue, s_base - off + 8), c);
            }
            if (COORD + r < EXTENT) {
                res0 = svmla_f64_m(ptrue, res0,
                                   svld1_f64(ptrue, s_base + off), c);
                res1 = svmla_f64_m(ptrue, res1,
                                   svld1_f64(ptrue, s_base + off + 8), c);
            }
        }
    }

    double result[B_TILE];
    svst1_f64(ptrue, result, res0);
    svst1_f64(ptrue, result + 8, res1);

    for (int j = 0; j < B_TILE; ++j) {
        fnv_u64(*(uint64_t *)&result[j]);
        if (result[j] != expected[j]) {
            fprintf(stderr, "lane %2d result=%.1f expected=%.1f\n",
                    j, result[j], expected[j]);
            ++g_fails;
        }
    }

    printf("SDCSHIELD_FAILS=%u\n", g_fails);
    printf("%016llx\n", (unsigned long long)fnv);
    return g_fails ? 1 : 0;
}

/* sme_fmopa_dual.c — dual-channel extraction of sdcshield test
 * `sme_fmopa_stress_arm` (PR #237 seed-randomized form) for CHAOS/gem5
 * SE-O3 fault injection (plan 2026-10-13-sve-sme-fi-eval Task 5).
 *
 * Kernel (from the test's sme_fmopa_kernel): SMSTART sm/za; ZERO {za};
 * K_FMOPA rounds of FMOPA za0.s (outer-product accumulate, f32) over
 * per-round operand vectors; ZA readout via st1w {za0h.s[w12,0]} rows.
 *
 * Channels:
 *   A — byte-exact compare of the readout tile against a scalar fmaf
 *       golden recomputed from the SAME inputs with the same op order.
 *       HONEST BOUNDARY (F4): gem5 implements FMOPA as fplib mul+add
 *       (double rounding); where that diverges from single-rounding fmaf
 *       the compare would fire on an UNINJECTED run. The no-injection
 *       baseline therefore defines per-mode goldens for the FI campaign
 *       (checksum channel), and channel A's fmaf compare is reported
 *       alongside — a channel-A fire on an injected run is Detected only
 *       if the no-injection control for that mode is clean.
 *   B — FNV-1a over the readout tile bits (the primary FI oracle).
 *
 * Operands: |a|,|b| < 0.5625 (the test's bound: 64-round f32 sums stay
 * below 21 — no overflow/NaN, flipped bits survive).
 *   fixed  — (k*37+i*11)%64/64.0 - 0.28125 (pre-PR#237 formula)
 *   random — xorshift32-derived uniform in (-0.5625, 0.5625)
 *
 * argv: [fixed|random] [seed]
 * Build: clang -static -O2 -march=armv9-a+sve+sme -Wall -Wextra \
 *          -o sme_fmopa_dual sme_fmopa_dual.c -lm
 * Run:   gem5.opt configs/se/arm_chaos.py --cmd <bin> --sme_vl 4 \
 *          --workload_args "random 1"
 */
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#define N_F32       16     /* tile side: SVL=512bit => 16 f32 lanes */
#define K_FMOPA     64     /* outer-product rounds (the test's count) */

static uint32_t xs_state;
static uint32_t xs32(void)
{
    xs_state ^= xs_state << 13;
    xs_state ^= xs_state >> 17;
    xs_state ^= xs_state << 5;
    return xs_state;
}
static float rnd_abs_f32(void)   /* uniform [0, 0.5625) */
{
    return (float)(xs32() >> 8) / (float)(1u << 24) * 0.5625f;
}

static unsigned g_fails = 0;
static uint64_t fnv = 1469598103934665603ULL;
static void fnv_u32(uint32_t v)
{
    fnv ^= v & 0xFF;         fnv *= 1099511628211ULL;
    fnv ^= (v >> 8) & 0xFF;  fnv *= 1099511628211ULL;
    fnv ^= (v >> 16) & 0xFF; fnv *= 1099511628211ULL;
    fnv ^= (v >> 24) & 0xFF; fnv *= 1099511628211ULL;
}

int main(int argc, char **argv)
{
    const char *mode = (argc > 1) ? argv[1] : "random";
    const uint32_t seed = (argc > 2) ? (uint32_t)strtoul(argv[2], 0, 0) : 1;
    const int randomize = (strcmp(mode, "random") == 0);
    xs_state = seed ? seed : 1;

    /* Operand streams, layout [k * N_F32 + i] (the test's geometry). */
    static float a[K_FMOPA * N_F32], b[K_FMOPA * N_F32];
    for (int k = 0; k < K_FMOPA; ++k)
        for (int i = 0; i < N_F32; ++i) {
            const size_t ki = (size_t)k * N_F32 + i;
            if (randomize) {
                a[ki] = (xs32() & 1 ? -1.0f : 1.0f) * rnd_abs_f32();
                b[ki] = (xs32() & 1 ? -1.0f : 1.0f) * rnd_abs_f32();
            } else {
                a[ki] = (float)(((k * 37 + i * 11) % 64) / 64.0 - 0.28125);
                b[ki] = (float)(((k * 53 + i * 29) % 64) / 64.0 - 0.28125);
            }
        }

    /* Scalar golden with the identical operation order and the
     * single-rounding fma the hardware FMOPA accumulate performs. */
    static float golden[N_F32 * N_F32];
    memset(golden, 0, sizeof golden);
    for (int k = 0; k < K_FMOPA; ++k)
        for (int r = 0; r < N_F32; ++r)
            for (int c = 0; c < N_F32; ++c)
                golden[(size_t)r * N_F32 + c] = fmaf(
                    a[(size_t)k * N_F32 + r], b[(size_t)k * N_F32 + c],
                    golden[(size_t)r * N_F32 + c]);

    /* SME kernel: one smstart/smstop window (the test's shape). */
    static float tile[N_F32 * N_F32];
    {
        const float *pa = a, *pb = b;
        float *pt = tile;
        asm volatile(
            "ldr x1, [%4]\n\t"              /* a            */
            "ldr x2, [%5]\n\t"              /* b            */
            "ldr x3, [%6]\n\t"              /* tile out     */
            "smstart sm\n\t"
            "smstart za\n\t"
            "zero {za}\n\t"
            "ptrue p0.s\n\t"
            "ptrue p1.s\n\t"
            "mov x9, #0\n"                  /* k = 0        */
            "1:\n\t"
            "cmp x9, #64\n\t"
            "b.ge 2f\n\t"
            "add x10, x1, x9, lsl #6\n\t"   /* &a[k*16]     */
            "add x11, x2, x9, lsl #6\n\t"   /* &b[k*16]     */
            "ld1w {z0.s}, p0/z, [x10]\n\t"
            "ld1w {z1.s}, p0/z, [x11]\n\t"
            "fmopa za0.s, p0/m, p1/m, z0.s, z1.s\n\t"
            "add x9, x9, #1\n\t"
            "b 1b\n"
            "2:\n\t"
            "mov x9, #0\n"                  /* row = 0      */
            "3:\n\t"
            "cmp x9, #16\n\t"
            "b.ge 4f\n\t"
            "mov w12, w9\n\t"
            "add x13, x3, x9, lsl #6\n\t"   /* &out[r*16]   */
            "st1w {za0h.s[w12, 0]}, p0, [x13]\n\t"
            "add x9, x9, #1\n\t"
            "b 3b\n"
            "4:\n\t"
            "smstop za\n\t"
            "smstop sm\n\t"
            : : "r"(&pa), "r"(&pb), "r"(&pt),
                "r"(pa), "r"(pb), "r"(pt)
            : "x1", "x2", "x3", "x9", "x10", "x11", "x13", "w12",
              "z0", "z1", "p0", "p1", "memory");
    }

    /* Channel A: byte-exact vs the scalar golden. */
    for (size_t i = 0; i < N_F32 * N_F32; ++i) {
        fnv_u32(*(uint32_t *)&tile[i]);
        if (tile[i] != golden[i]) {
            if (g_fails == 0)
                fprintf(stderr, "tile mismatch @%zu hw=%.9g sw=%.9g\n",
                        i, tile[i], golden[i]);
            ++g_fails;
        }
    }

    printf("SDCSHIELD_FAILS=%u\n", g_fails);
    printf("%016llx\n", (unsigned long long)fnv);
    return g_fails ? 1 : 0;
}

/* sme_za_tileview_dual.c — dual-channel extraction of sdcshield test
 * `sme_za_tileview_arm` (PR #237 seed-randomized form) for CHAOS/gem5
 * SE-O3 fault injection (plan 2026-10-13-sve-sme-fi-eval Task 6).
 *
 * Kernel (the test's ZA tile-view semantics, f64 at SVL=512):
 *   - load row-major a into za0h via ld1d {za0h.d[w12, 0]}
 *   - round trip  : st1d {za0h.d[w12, 0]}  -> byte-identical a
 *   - transpose   : st1d {za0v.d[w12, 0]}  -> column w12 = a's row image
 *   - slice shift : za0h.d[r, 1] read      -> row written via r+1 mod n
 * Tiles are pure data permutations — no rounding — so channel A is a
 * direct byte-exact permutation golden (unlike the FMOPA kernel, no
 * semantic adaptation is needed).
 *
 *   fixed  — (i*131+j)%977 + 0.5*(i+1) exact doubles (pre-PR#237)
 *   random — (xorshift64()%1024)*64 + (i*n+j) exact distinct integers
 *            (the PR #237 injective-index form)
 *
 * argv: [fixed|random] [seed]
 * Build: clang -static -O2 -march=armv9-a+sve+sme -Wall -Wextra \
 *          -o sme_za_tileview_dual sme_za_tileview_dual.c -lm
 * Run:   gem5.opt configs/se/arm_chaos.py --cmd <bin> --sme_vl 4 \
 *          --workload_args "random 1"
 */
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

#define N_D 8     /* tile side: SVL=512bit => 8 f64 slices */

static uint64_t xs_state;
static uint64_t xs64(void)
{
    xs_state ^= xs_state << 13;
    xs_state ^= xs_state >> 7;
    xs_state ^= xs_state << 17;
    return xs_state;
}

static unsigned g_fails = 0;
static uint64_t fnv = 1469598103934665603ULL;
static void fnv_u64(uint64_t v)
{
    for (int i = 0; i < 8; ++i) {
        fnv ^= (v >> (8 * i)) & 0xFF;
        fnv *= 1099511628211ULL;
    }
}

/* One smstart/smstop window performing the three views of a into the
 * three output tiles (row-major [r*n + c]). Registers follow the test's
 * kernel shape: w12 slice select, x1 base of the source row. */
static void za_tileview_kernel(const double *a, double *id_a, double *tr_a,
                               double *rot_a)
{
    asm volatile(
        "smstart sm\n\t"
        "smstart za\n\t"
        "zero {za}\n\t"
        "ptrue p0.d\n\t"
        "mov x9, #0\n"                  /* row = 0        */
        "1:\n\t"
        "cmp x9, #8\n\t"
        "b.ge 2f\n\t"
        "mov w12, w9\n\t"
        "add x10, x0, x9, lsl #6\n\t"   /* &a[r*8]        */
        "ld1d {za0h.d[w12, 0]}, p0/z, [x10]\n\t"
        "add x9, x9, #1\n\t"
        "b 1b\n"
        "2:\n\t"
        "mov x9, #0\n"                  /* horizontal readout */
        "3:\n\t"
        "cmp x9, #8\n\t"
        "b.ge 4f\n\t"
        "mov w12, w9\n\t"
        "add x13, x1, x9, lsl #6\n\t"
        "st1d {za0h.d[w12, 0]}, p0, [x13]\n\t"
        "add x9, x9, #1\n\t"
        "b 3b\n"
        "4:\n\t"
        "mov x9, #0\n"                  /* vertical (transpose) readout */
        "5:\n\t"
        "cmp x9, #8\n\t"
        "b.ge 6f\n\t"
        "mov w12, w9\n\t"
        "add x13, x2, x9, lsl #6\n\t"
        "st1d {za0v.d[w12, 0]}, p0, [x13]\n\t"
        "add x9, x9, #1\n\t"
        "b 5b\n"
        "6:\n\t"
        "mov x9, #0\n"                  /* slice-shift readout: za0h.d[r,1] */
        "7:\n\t"
        "cmp x9, #8\n\t"
        "b.ge 8f\n\t"
        "mov w12, w9\n\t"
        "add w14, w9, #1\n\t"           /* r+1            */
        "and w14, w14, #7\n\t"          /* r+1 mod 8      */
        "add x13, x3, x9, lsl #6\n\t"
        "st1d {za0h.d[w14, 1]}, p0, [x13]\n\t"
        "add x9, x9, #1\n\t"
        "b 7b\n"
        "8:\n\t"
        "smstop za\n\t"
        "smstop sm\n\t"
        : : "r"(a), "r"(id_a), "r"(tr_a), "r"(rot_a)
        : "x9", "x10", "x13", "w12", "w14", "p0", "memory");
}

int main(int argc, char **argv)
{
    const char *mode = (argc > 1) ? argv[1] : "random";
    const uint64_t seed = (argc > 2) ? strtoull(argv[2], 0, 0) : 1;
    const int randomize = (strcmp(mode, "random") == 0);
    xs_state = seed ? seed : 1;

    static double a[N_D * N_D], id_a[N_D * N_D], tr_a[N_D * N_D],
                  rot_a[N_D * N_D];
    for (int i = 0; i < N_D; ++i)
        for (int j = 0; j < N_D; ++j) {
            const size_t ij = (size_t)i * N_D + j;
            if (randomize)
                a[ij] = (double)((xs64() % 1024) * 64 + (i * N_D + j));
            else
                a[ij] = (double)((i * 131 + j) % 977) + 0.5 * (i + 1);
        }

    za_tileview_kernel(a, id_a, tr_a, rot_a);

    /* Channel A: permutation goldens, byte-exact. */
    for (int i = 0; i < N_D; ++i)
        for (int j = 0; j < N_D; ++j) {
            const size_t ij = (size_t)i * N_D + j;
            const size_t ji = (size_t)j * N_D + i;
            const size_t rot = (size_t)((i + 1) % N_D) * N_D + j;
            fnv_u64(*(uint64_t *)&id_a[ij]);
            fnv_u64(*(uint64_t *)&tr_a[ij]);
            fnv_u64(*(uint64_t *)&rot_a[ij]);
            if (id_a[ij] != a[ij]) {
                if (g_fails == 0)
                    fprintf(stderr, "id mismatch @(%d,%d)\n", i, j);
                ++g_fails;
            }
            if (tr_a[ij] != a[ji]) {
                if (g_fails == 0)
                    fprintf(stderr, "transpose mismatch @(%d,%d)\n", i, j);
                ++g_fails;
            }
            if (rot_a[ij] != a[rot]) {
                if (g_fails == 0)
                    fprintf(stderr, "slice-shift mismatch @(%d,%d)\n", i, j);
                ++g_fails;
            }
        }

    printf("SDCSHIELD_FAILS=%u\n", g_fails);
    printf("%016llx\n", (unsigned long long)fnv);
    return g_fails ? 1 : 0;
}

