/* za_semantics_probe.c — determine gem5's actual za0h.d[Rn, imm] semantics
 * per SVL: which slice does index+imm select? Load n rows of distinct
 * sentinels, read za0h.d[r, 0] and za0h.d[r, 1] for r in 0..n-1, print.
 * Build: clang -static -O2 -march=armv9-a+sve+sme -o za_semantics_probe .c */
#include <stdio.h>
#include <stdint.h>
#include <stddef.h>

int main(void)
{
    int64_t svl = 0;
    asm volatile("rdsvl %0, #1" : "=r"(svl));
    const int n = (int)(svl / 8);
    printf("SVL=%ld bytes, n=%d f64 slices\n", (long)svl, n);

    /* sentinels: row r, col c -> 1000*r + c */
    static double a[16 * 16];
    for (int r = 0; r < n; ++r)
        for (int c = 0; c < n; ++c)
            a[(size_t)r * n + c] = 1000.0 * r + c;

